    rows = []
    for letter, item, slot in self._letter_items():
        if slot is None:
            price = int(item["value"] * mult)
            rows.append({"text": f"{letter} - {item['name']} - sell for ${price}",
                         "action": f"trader_sell:{letter}", "enabled": True})
    if not rows:
