# Action dispatch
# ------------------------------------------------------------------
def dispatch(self, action):
    if not action:
        return
    if ":" in action:
        verb, arg = action.split(":", 1)
    else:
        verb, arg = action, None

    if verb == "goto":
        self.screen = arg
        return

    handler = getattr(self, f"_action_{verb}", None)
    if handler is None:
        return  # unknown action - ignore defensively rather than crash
    if arg is not None:
        handler(arg)
    else:
        handler()

