    for btn in data.get('buttons', []):
        action = btn.get('action')
        if not action:
            continue
        if action.startswith('goto:'):
            tgt = action.split(':',1)[1]
            if tgt not in ui:
                errors.append((sid, action, 'goto target missing'))

# ---------- controller screen checks ----------

def setup_controller_for_screen(screen):
    c = GameController()
    # Build a valid hero for most screens
    c.pending_name = 'TestHero'
    c.pending_class = 'Hitter'
    c._action_confirm_character()
    if c.engine is None:
        c.engine = HeroAdventureEngine('TestHero', 'Hitter')

    # common state prep
    if screen in ('high_scores',):
        c.scores = [
            {'name':'A','class':'Hitter','score':1000,'result':'Tavern'},
            {'name':'B','class':'Blaster','score':2000,'result':'Bought Cottage'},
        ]
    if screen == 'item_detail':
        item = c.engine.generate_random_item(leg_num=1)
        c.engine.inventory.append(item)
        c.selected_item_letter = c.LETTERS[0]
    if screen in ('combat','super_monster_preview'):
        m='Goblin'
        d=MONSTERS[m]
        c.ctx.update({'monster_name':m,'monster_fighting':d['fighting'],'monster_defending':d['defending'],'monster_magic':d['magic'], 'allow_run':True, 'combat_kind':'regular'})
    if screen == 'dungeon_found':
        leg=LEGS[c.engine.current_leg_idx]
        c.dungeon_pending = leg['dungeons'][0]
        c.ctx = {'dungeon_name': c.dungeon_pending['name'], 'dungeon_boss': c.dungeon_pending['boss']}
    if screen in ('dungeon_floor_preview','dungeon_boss_preview'):
        c.engine.enter_dungeon(LEGS[c.engine.current_leg_idx]['dungeons'][0])
        if screen == 'dungeon_boss_preview':
            c.engine.dungeon_event_count = 5
        mon = c.engine.get_dungeon_floor_monster()
        d=MONSTERS[mon]
        c.ctx = {'floor_monster': mon, 'floor_number': min(c.engine.dungeon_event_count+1,5), 'monster_fighting':d['fighting'],'monster_defending':d['defending'],'monster_magic':d['magic'], 'is_boss': c.engine.dungeon_event_count>=5}
    if screen == 'dungeon_victory':
        c.ctx={'treasure':300}
    if screen in ('magic_shrine_event','loot_screen'):
        items=[c.engine.generate_random_item(1)]
        c.ctx={'loot_cash':123,'loot_items':items,'loot_lines':c._format_loot_lines(items)}
    if screen in ('tavern_event','camping_event'):
        c.ctx = {'resolved': False}
    if screen == 'wandering_trader':
        c.trader_offer = [c.engine.generate_random_item(1) for _ in range(2)]
    if screen == 'capital_result':
        c.ctx = {'final_house':'Tavern','final_pension':500,'final_score':500}
    if screen == 'death':
        c.engine.death_reason = 'slain by Goblin'

    # for pre-game screens
    if screen in ('front_page','character_creation','rules','rules_journey','rules_scoring','rules_character_creation','credits'):
        c.engine = None
    if screen == 'character_creation':
        c.pending_name='TestHero'
        c.pending_class='Hitter'

    c.screen = screen
    return c

for sid in sorted(ui.keys()):
    # context rendering check
    try:
        c = setup_controller_for_screen(sid)
        _ = c.get_context()
    except Exception as e:
        errors.append((sid, 'get_context', repr(e)))
        continue

    # actions in buttons
    for btn in ui[sid].get('buttons', []):
        action = btn.get('action')
        if not action:
            continue
        try:
            c = setup_controller_for_screen(sid)
            c.dispatch(action)
        except Exception as e:
            errors.append((sid, action, repr(e)))

    # actions in dynamic lists
    try:
        c = setup_controller_for_screen(sid)
        ctx = c.get_context()
        for k,v in ctx.items():
            if k.startswith('list_') and isinstance(v,list):
                for row in v:
                    a = row.get('action') if isinstance(row, dict) else None
                    if a:
                        try:
                            c2 = setup_controller_for_screen(sid)
                            c2.dispatch(a)
                        except Exception as e:
                            errors.append((sid, f'list:{a}', repr(e)))
    except Exception as e:
        errors.append((sid, 'list_build', repr(e)))

# ---------- random walk smoke ----------
for seed in range(5):
    random.seed(seed)
    c = GameController()
    c.pending_name = 'Walker'
    c.pending_class = 'Hitter'
    c._action_confirm_character()
    c.screen = 'journey'
    ok = True
    for step in range(400):
        sid = c.screen
        if sid not in ui:
            # controller-only screen fallback to continue action when available
            if sid in ('combat_result',):
                act = 'combat_continue'
            else:
                act = 'continue_journey' if sid != 'death' else 'death_continue'
            try:
                c.dispatch(act)
            except Exception as e:
                errors.append((f'random_walk_seed_{seed}', act, repr(e)))
                ok = False
                break
            continue

        ctx = c.get_context()
        acts = [b.get('action') for b in ui[sid].get('buttons', []) if b.get('action')]
        for k,v in ctx.items():
            if k.startswith('list_') and isinstance(v,list):
                acts.extend([row.get('action') for row in v if isinstance(row,dict) and row.get('action')])

        # choose a likely-progress action first
        pref = ['advance_event','continue_journey','combat_continue','loot_continue','magic_shrine_continue','dungeon_victory_continue','leave_trader','levelup_continue']
        action = next((a for a in pref if a in acts), None)
        if action is None:
            action = random.choice(acts) if acts else None
        if not action:
            break
        if action == 'confirm_character':
            c.pending_name = 'Walker'
            c.pending_class = c.pending_class or 'Hitter'
        try:
            c.dispatch(action)
        except Exception as e:
            errors.append((f'random_walk_seed_{seed}', action, repr(e)))
            ok = False
            break
    if not ok:
        warnings.append(f'random walk failed seed {seed}')

print('ERROR_COUNT', len(errors))
for e in errors[:30]:
    print('ERR', e)
if len(errors)>30:
    print('... truncated ...')
print('WARNING_COUNT', len(warnings))
for w in warnings:
    print('WARN', w)
